static const DashboardCjk48GlyphEntry* findDashboardCjk48Glyph(uint32_t cp) { size_t lo=0,hi=kDashboardCjk48Table.count; while(lo<hi){size_t mid=lo+(hi-lo)/2;if(kDashboardCjk48Table.entries[mid].codepoint==cp)return &kDashboardCjk48Table.entries[mid];if(kDashboardCjk48Table.entries[mid].codepoint<cp)lo=mid+1;else hi=mid;}return nullptr;}
